import{_ as e,o as t,c as n,a2 as r}from"./chunks/framework.DtFGJNng.js";const p=JSON.parse('{"title":"Dokumentasi deuz","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"README.md","lastUpdated":1794565319000}'),i={name:"index.md"};function d(s,a,u,l,o,h){return t(),n("div",null,[...a[0]||(a[0]=[r('<h1 id="dokumentasi-deuz" tabindex="-1">Dokumentasi deuz <a class="header-anchor" href="#dokumentasi-deuz" aria-label="Permalink to &quot;Dokumentasi deuz&quot;">​</a></h1><p>deuz membantu tim <strong>menyepakati apa yang akan dibangun sebelum membangunnya</strong>, dan membuat serah terima antar peran menjadi jelas. Analyst menulis perilaku yang diinginkan, designer mengubahnya menjadi layar, backend dan frontend menyepakati API, lalu backend, frontend, dan QA bekerja paralel. Alur yang sama juga bisa dipakai satu orang bersama AI agent.</p><p>Kalau hanya sempat membaca dua halaman, baca ini:</p><ol><li><a href="./memulai">Memulai</a>: pasang deuz dan jalankan satu work dari proposal sampai archive.</li><li><a href="./konsep-singkat">Konsep singkat</a>: seluruh cara berpikir deuz dalam satu halaman.</li></ol><blockquote><p>deuz punya dua bagian. <strong>Skill</strong> (<code>/deuz:new</code>, <code>/deuz:continue</code>, …) diketik di chat AI agent (Claude Code). <strong>CLI</strong> (<code>deuz status</code>, <code>deuz ready</code>, …) dijalankan di terminal, dan juga dipanggil oleh skill di belakang layar. Bedanya dijelaskan di <a href="./skill-dan-cli">Skill dan CLI</a>.</p></blockquote><h2 id="pilih-jalurmu" tabindex="-1">Pilih jalurmu <a class="header-anchor" href="#pilih-jalurmu" aria-label="Permalink to &quot;Pilih jalurmu&quot;">​</a></h2><p><strong>Saya baru mengenal deuz.</strong> Mulai dari <a href="./memulai">Memulai</a>, lalu baca <a href="./konsep-singkat">Konsep singkat</a>. Istilah yang asing ada di <a href="./glosarium">Glosarium</a>.</p><p><strong>Saya ingin tahu kenapa deuz dibuat seperti ini.</strong> Baca <a href="./alur-berpikir">Alur berpikir</a>, lalu <a href="./decisions">Keputusan desain</a> untuk alasan tiap keputusan dibanding OpenSpec.</p><p><strong>Saya Product System Analyst.</strong> Baca <a href="./alur-kerja">Alur kerja</a>, <a href="./persetujuan-bisnis">Persetujuan bisnis</a>, dan <a href="./menulis-spec">Menulis spec yang baik</a>. Panduan isi <a href="./artifacts/proposal">proposal</a> dan <a href="./artifacts/specs">spec</a> menunjukkan contoh lengkapnya.</p><p><strong>Saya engineer (backend atau frontend).</strong> Baca <a href="./alur-kerja">Alur kerja</a>, terutama jalur engineer untuk bug fix dan perubahan teknis. Lalu panduan <a href="./artifacts/api-contract">API contract</a> dan <a href="./artifacts/tasks">tasks</a>.</p><p><strong>Saya designer atau QA.</strong> Panduan <a href="./artifacts/ui-design">ui-design</a> dan <a href="./artifacts/tasks-test">tasks-test</a> menjelaskan apa yang kamu terima dan apa yang kamu serahkan.</p><p><strong>Proyek saya sudah punya banyak kode.</strong> Kamu tidak perlu mendokumentasikan semuanya dulu. Baca <a href="./proyek-existing">Proyek yang sudah berjalan</a>.</p><p><strong>Saya belajar dari contoh.</strong> <a href="./contoh">Contoh</a> menelusuri empat kasus nyata dari awal sampai akhir.</p><p><strong>Tim saya ingin menyesuaikan deuz.</strong> <a href="./kustomisasi">Kustomisasi</a> membahas <code>config.yaml</code>: peran, homes, override owner, aturan tambahan, dan fork schema.</p><p><strong>Ada yang tidak jalan.</strong> <a href="./masalah-umum">Masalah umum</a> mengumpulkan pesan penolakan CLI dan cara mengatasinya.</p><h2 id="peta-lengkap" tabindex="-1">Peta lengkap <a class="header-anchor" href="#peta-lengkap" aria-label="Permalink to &quot;Peta lengkap&quot;">​</a></h2><h3 id="mulai-di-sini" tabindex="-1">Mulai di sini <a class="header-anchor" href="#mulai-di-sini" aria-label="Permalink to &quot;Mulai di sini&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Halaman</th><th>Isi</th></tr></thead><tbody><tr><td><a href="./memulai">Memulai</a></td><td>Instalasi, <code>/deuz:init</code>, dan satu work end to end</td></tr><tr><td><a href="./konsep-singkat">Konsep singkat</a></td><td>Work, artifact, peran, status, homes, delta, archive, gate, dalam satu halaman</td></tr><tr><td><a href="./skill-dan-cli">Skill dan CLI</a></td><td>Apa yang diketik di chat agent dan apa yang dijalankan di terminal</td></tr></tbody></table><h3 id="dipakai-sehari-hari" tabindex="-1">Dipakai sehari-hari <a class="header-anchor" href="#dipakai-sehari-hari" aria-label="Permalink to &quot;Dipakai sehari-hari&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Halaman</th><th>Isi</th></tr></thead><tbody><tr><td><a href="./alur-kerja">Alur kerja</a></td><td>Jalur analyst dan jalur engineer, tugas tiap peran, kapan artifact di-skip</td></tr><tr><td><a href="./persetujuan-bisnis">Persetujuan bisnis</a></td><td>Gate 1 dan Gate 2, mencatat hasil rapat, pertanyaan <code>open-blocking</code></td></tr><tr><td><a href="./menulis-spec">Menulis spec yang baik</a></td><td>Requirement, scenario, tabel contoh, bahasa bisnis, ukuran capability</td></tr><tr><td><a href="./contoh">Contoh</a></td><td>Fitur baru dengan gate, bug fix, perubahan perilaku, adopsi di kode yang sudah ada</td></tr><tr><td><a href="./tim-dan-git">Tim dan Git</a></td><td>Work dalam branch dan pull request, review per artifact, solo ke tim</td></tr><tr><td><a href="./proyek-existing">Proyek yang sudah berjalan</a></td><td>Memakai deuz tanpa harus mendokumentasikan seluruh sistem</td></tr><tr><td><a href="./masalah-umum">Masalah umum</a></td><td>Pesan penolakan dan error yang sering muncul</td></tr></tbody></table><h3 id="panduan-per-artifact" tabindex="-1">Panduan per artifact <a class="header-anchor" href="#panduan-per-artifact" aria-label="Permalink to &quot;Panduan per artifact&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Halaman</th><th>Isi</th></tr></thead><tbody><tr><td><a href="./artifacts/README">Ringkasan artifact</a></td><td>Siapa menulis apa, dan urutannya</td></tr><tr><td><a href="./artifacts/proposal">proposal</a>, <a href="./artifacts/specs">specs</a>, <a href="./artifacts/ui-design">ui-design</a>, <a href="./artifacts/api-contract">api-contract</a>, <a href="./artifacts/tasks">tasks</a>, <a href="./artifacts/tasks-test">tasks-test</a></td><td>Isi, contoh, dan kesalahan yang paling mahal</td></tr></tbody></table><h3 id="memahami-lebih-dalam" tabindex="-1">Memahami lebih dalam <a class="header-anchor" href="#memahami-lebih-dalam" aria-label="Permalink to &quot;Memahami lebih dalam&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Halaman</th><th>Isi</th></tr></thead><tbody><tr><td><a href="./filosofi">Filosofi</a></td><td>Cerita di balik deuz: enam minggu mencari alur yang cocok, dan asal nama Deuz</td></tr><tr><td><a href="./alur-berpikir">Alur berpikir</a></td><td>Kenapa spec-driven, prinsip desain deuz, bedanya dengan OpenSpec</td></tr><tr><td><a href="./decisions">Keputusan desain</a></td><td>Setiap keputusan: apa yang dilakukan OpenSpec, apa pilihan deuz, dan alasannya</td></tr><tr><td><a href="./manifest">Manifest work</a></td><td>Format <code>.deuz.yaml</code> untuk editor yang menampilkan navigasi antar dokumen</td></tr><tr><td><a href="./faq">FAQ</a></td><td>Pertanyaan yang sering muncul</td></tr><tr><td><a href="./glosarium">Glosarium</a></td><td>Semua istilah di satu tempat</td></tr></tbody></table><h3 id="menyesuaikan" tabindex="-1">Menyesuaikan <a class="header-anchor" href="#menyesuaikan" aria-label="Permalink to &quot;Menyesuaikan&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Halaman</th><th>Isi</th></tr></thead><tbody><tr><td><a href="./kustomisasi">Kustomisasi</a></td><td><code>config.yaml</code>, override owner, aturan per artifact, fork schema</td></tr></tbody></table><h2 id="untuk-kontributor-deuz" tabindex="-1">Untuk kontributor deuz <a class="header-anchor" href="#untuk-kontributor-deuz" aria-label="Permalink to &quot;Untuk kontributor deuz&quot;">​</a></h2><p>Aturan yang dijalankan CLI dan skill ada di <a href="https://github.com/alfagift-ai-mastery/deuz/blob/main/core/RULES.md" target="_blank" rel="noreferrer"><code>core/RULES.md</code></a> (Bahasa Inggris, karena dibaca agent). Desain dan rencana implementasi ada di <a href="https://github.com/alfagift-ai-mastery/deuz/tree/main/docs/superpowers" target="_blank" rel="noreferrer"><code>docs/superpowers/</code></a>.</p>',28)])])}const k=e(i,[["render",d]]);export{p as __pageData,k as default};
